public class OverloadDescriberTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("describe(5)", "int: 5", OverloadDescriber.describe(5));
        check("describe(2.5)", "double: 2.5", OverloadDescriber.describe(2.5));
        check("describe(\"hi\")", "text: hi", OverloadDescriber.describe("hi"));
        check("describe(-42)", "int: -42", OverloadDescriber.describe(-42));
        check("describe(0.5)", "double: 0.5", OverloadDescriber.describe(0.5));
        check("describe(7.0)", "double: 7.0", OverloadDescriber.describe(7.0));
        check("describe(\"\")", "text: ", OverloadDescriber.describe(""));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

